// HasConversation applies the HasEdge predicate on the "conversation" edge.
func HasConversation() predicate.KaguyaTitleJob {
	return predicate.KaguyaTitleJob(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, ConversationTable, ConversationColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasConversationWith applies the HasEdge predicate on the "conversation" edge with a given conditions (other predicates).
func HasConversationWith(preds ...predicate.KaguyaConversation) predicate.KaguyaTitleJob {
	return predicate.KaguyaTitleJob(func(s *sql.Selector) {
		step := newConversationStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.KaguyaTitleJob) predicate.KaguyaTitleJob {
	return predicate.KaguyaTitleJob(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.KaguyaTitleJob) predicate.KaguyaTitleJob {
	return predicate.KaguyaTitleJob(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.KaguyaTitleJob) predicate.KaguyaTitleJob {
	return predicate.KaguyaTitleJob(sql.NotPredicates(p))
}
